begin;
create table app.campuses(school_id uuid not null,id uuid not null default gen_random_uuid(),name text not null check(length(btrim(name))between 1 and 200),location text,reason text not null,created_by uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,created_by)references app.memberships(school_id,actor_id),check(location is null or length(location)<=1000));
create table app.campus_retirements(school_id uuid not null,campus_id uuid not null,reason text not null,retired_by uuid not null,retired_at timestamptz not null default clock_timestamp(),primary key(school_id,campus_id),foreign key(school_id,campus_id)references app.campuses(school_id,id),foreign key(school_id,retired_by)references app.memberships(school_id,actor_id));
create table app.class_campus_revisions(school_id uuid not null,id uuid not null default gen_random_uuid(),class_id uuid not null,campus_id uuid,revision integer not null check(revision>0),reason text not null,approved_by uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,class_id,revision),foreign key(school_id,class_id)references app.classes(school_id,id),foreign key(school_id,campus_id)references app.campuses(school_id,id),foreign key(school_id,approved_by)references app.memberships(school_id,actor_id));
create table app.learning_support_approvals(school_id uuid not null,id uuid not null default gen_random_uuid(),learner_id uuid not null,course_id uuid not null,assessment_id uuid,title text not null check(length(btrim(title))between 1 and 200),instructions text not null check(length(btrim(instructions))between 1 and 4000),effective_from date not null,effective_to date not null,student_visible boolean not null,parent_visible boolean not null,reason text not null check(length(btrim(reason))between 1 and 2000),approved_by uuid not null,approved_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id),foreign key(school_id,course_id)references app.courses(school_id,id),foreign key(school_id,assessment_id)references app.assessments(school_id,id),foreign key(school_id,approved_by)references app.memberships(school_id,actor_id),check(effective_to>=effective_from));
create table app.learning_support_revocations(school_id uuid not null,support_id uuid not null,reason text not null check(length(btrim(reason))between 1 and 2000),revoked_by uuid not null,revoked_at timestamptz not null default clock_timestamp(),primary key(school_id,support_id),foreign key(school_id,support_id)references app.learning_support_approvals(school_id,id),foreign key(school_id,revoked_by)references app.memberships(school_id,actor_id));
do $$declare tab text;begin foreach tab in array array['campuses','campus_retirements','class_campus_revisions','learning_support_approvals','learning_support_revocations']loop
 execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);execute format('revoke all on app.%I from public,anon,authenticated,service_role,cuevo_api,cuevo_worker',tab);execute format('create trigger immutable_history before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger immutable_truncate before truncate on app.%I for each statement execute function internal.academic_history_immutable()',tab);
end loop;end$$;
create function internal.campus_support_command(command_name text,target_id uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();role_name text:="authorization".current_role("authorization".school_id());support app.learning_support_approvals;latest integer;rid uuid;reservation jsonb;receipt jsonb;begin
 if not"authorization".school_operations_access(school)or role_name is null or role_name not in('admin','coordinator')or(command_name like'campus.%'or command_name='class.campus')and role_name<>'admin'then raise exception 'School approved context command denied'using errcode='42501';end if;
 if payload is null or jsonb_typeof(payload)<>'object'or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 2000 then raise exception 'Explicit school approval reason required'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(school::text||':campus-support',0));
 perform pg_advisory_xact_lock(hashtextextended(school::text||':school-access-mutations',0));
 role_name:="authorization".current_role(school);
 if not"authorization".school_operations_access(school)or role_name is null or role_name not in('admin','coordinator')or(command_name like'campus.%'or command_name='class.campus')and role_name<>'admin'then raise exception 'School approved context command denied'using errcode='42501';end if;
 if command_name='class.campus'then perform 1 from app.classes where school_id=school and id=target_id for share;
 elsif command_name='support.create'then perform 1 from app.courses where school_id=school and id=(payload->>'courseId')::uuid for update;perform 1 from app.memberships where school_id=school and actor_id=(payload->>'learnerId')::uuid for share;perform 1 from app.enrollments where school_id=school and student_actor_id=(payload->>'learnerId')::uuid order by class_id for share;end if;
 if command_name='class.campus'then
  if not(payload?&array['campusId','expectedRevision','reason','confirmConfiguration'])or jsonb_typeof(payload->'campusId')not in('string','null')or jsonb_typeof(payload->'expectedRevision')is distinct from'number'or payload->>'expectedRevision'!~'^[0-9]+$'or payload-'campusId'-'expectedRevision'-'reason'-'confirmConfiguration'<>'{}'::jsonb or payload->'confirmConfiguration'is distinct from'true'::jsonb or not exists(select 1 from app.classes where school_id=school and id=target_id and status='active')or(payload->>'campusId'is not null and not exists(select 1 from app.campuses campus where campus.school_id=school and campus.id=(payload->>'campusId')::uuid and not exists(select 1 from app.campus_retirements retired where retired.school_id=school and retired.campus_id=campus.id)))then raise exception 'Current class and campus approval required'using errcode='22023';end if;
 elsif command_name='campus.retire'then
  if payload-'reason'-'confirmRetirement'<>'{}'::jsonb or payload->'confirmRetirement'is distinct from'true'::jsonb or not exists(select 1 from app.campuses where school_id=school and id=target_id)then raise exception 'Explicit campus retirement required'using errcode='22023';end if;
 elsif command_name='support.create'then
  if internal.learning_published_content(school,'course',(payload->>'courseId')::uuid)is null then raise exception 'Current published learning source required'using errcode='22023';end if;
  if not"authorization".academic_access(school)or payload-'learnerId'-'courseId'-'assessmentId'-'title'-'instructions'-'effectiveFrom'-'effectiveTo'-'studentVisible'-'parentVisible'-'reason'-'confirmApproval'<>'{}'::jsonb or payload->'confirmApproval'is distinct from'true'::jsonb or jsonb_typeof(payload->'studentVisible')is distinct from'boolean'or jsonb_typeof(payload->'parentVisible')is distinct from'boolean'or jsonb_typeof(payload->'title')is distinct from'string'or jsonb_typeof(payload->'instructions')is distinct from'string'or jsonb_typeof(payload->'effectiveFrom')is distinct from'string'or jsonb_typeof(payload->'effectiveTo')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200 or length(btrim(payload->>'instructions'))not between 1 and 4000 or(payload->>'effectiveTo')::date<(payload->>'effectiveFrom')::date or not"authorization".current_learner_course(school,(payload->>'courseId')::uuid,(payload->>'learnerId')::uuid)or not"authorization".can_view_person(school,(payload->>'learnerId')::uuid)or not"authorization".can_read_course(school,(payload->>'courseId')::uuid)or(payload->>'assessmentId'is not null and not exists(select 1 from app.assessments where school_id=school and id=(payload->>'assessmentId')::uuid and course_id=(payload->>'courseId')::uuid))then raise exception 'Current exact learner learning support scope required'using errcode='42501';end if;
 elsif command_name='support.revoke'then
  select*into support from app.learning_support_approvals where school_id=school and id=target_id;
  if support.id is null or jsonb_typeof(payload->'expectedRevision')is distinct from'number'or payload->>'expectedRevision'!~'^[1-9][0-9]*$'or payload-'expectedRevision'-'reason'-'confirmRevocation'<>'{}'::jsonb or payload->'confirmRevocation'is distinct from'true'::jsonb or not"authorization".can_view_person(school,support.learner_id)or not"authorization".can_read_course(school,support.course_id)then raise exception 'Current support revocation denied'using errcode='42501';end if;
 elsif command_name='campus.create'then
  if payload-'name'-'location'-'reason'-'confirmConfiguration'<>'{}'::jsonb or payload->'confirmConfiguration'is distinct from'true'::jsonb or jsonb_typeof(payload->'name')is distinct from'string'or length(btrim(payload->>'name'))not between 1 and 200 or(payload->>'location'is not null and(jsonb_typeof(payload->'location')is distinct from'string'or length(payload->>'location')>1000))then raise exception 'School campus configuration required'using errcode='22023';end if;
 else raise exception 'Unknown school context command'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'school.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';end if;if reservation->>'state'<>'NEW'then raise exception 'School context command in progress'using errcode='22023';end if;
 if command_name='campus.create'then insert into app.campuses(school_id,name,location,reason,created_by)values(school,payload->>'name',payload->>'location',payload->>'reason',actor)returning id into rid;
 elsif command_name='class.campus'then select coalesce(max(revision),0)into latest from app.class_campus_revisions where school_id=school and class_id=target_id;if latest is distinct from(payload->>'expectedRevision')::integer then raise exception 'Class campus revision changed'using errcode='22023';end if;insert into app.class_campus_revisions(school_id,class_id,campus_id,revision,reason,approved_by)values(school,target_id,(payload->>'campusId')::uuid,latest+1,payload->>'reason',actor)returning id into rid;
 elsif command_name='campus.retire'then if exists(select 1 from app.class_campus_revisions current join app.classes class on class.school_id=current.school_id and class.id=current.class_id where current.school_id=school and current.campus_id=target_id and class.status='active'and not exists(select 1 from app.class_campus_revisions newer where newer.school_id=current.school_id and newer.class_id=current.class_id and newer.revision>current.revision))then raise exception 'Move current classes before campus retirement'using errcode='22023';end if;insert into app.campus_retirements(school_id,campus_id,reason,retired_by)values(school,target_id,payload->>'reason',actor);rid:=target_id;
 elsif command_name='support.create'then insert into app.learning_support_approvals(school_id,learner_id,course_id,assessment_id,title,instructions,effective_from,effective_to,student_visible,parent_visible,reason,approved_by)values(school,(payload->>'learnerId')::uuid,(payload->>'courseId')::uuid,(payload->>'assessmentId')::uuid,payload->>'title',payload->>'instructions',(payload->>'effectiveFrom')::date,(payload->>'effectiveTo')::date,(payload->>'studentVisible')::boolean,(payload->>'parentVisible')::boolean,payload->>'reason',actor)returning id into rid;
 else if(payload->>'expectedRevision')::integer<>1 or exists(select 1 from app.learning_support_revocations where school_id=school and support_id=target_id)then raise exception 'Support approval revision changed'using errcode='22023';end if;insert into app.learning_support_revocations(school_id,support_id,reason,revoked_by)values(school,target_id,payload->>'reason',actor);rid:=target_id;end if;
 receipt:=jsonb_build_object('id',rid,'revision',case when command_name='class.campus'then latest+1 when command_name='support.revoke'then 2 else 1 end);perform internal.append_audit('school.'||command_name,'school_operation',rid,request_id,'succeeded','{}');perform internal.enqueue_event('school.context.approved','school_context',rid,case when command_name='class.campus'then latest+1 when command_name='support.revoke'then 2 else 1 end,jsonb_build_object('command',command_name),md5('school-context:'||actor::text||':'||command_name||':'||command_key));perform internal.finish_command(command_key,'school.'||command_name,fingerprint,receipt);return receipt;
end$$;
create function internal.read_campus_page(page_limit integer,page_cursor uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();rows jsonb;begin
 if not"authorization".school_operations_access(school)or"authorization".current_role(school)not in('admin','coordinator')then raise exception 'Campus management read denied'using errcode='42501';end if;if page_limit is null or page_limit not between 1 and 25 then raise exception 'Bounded campus page required'using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',campus.id,'name',campus.name,'location',campus.location,'retired',exists(select 1 from app.campus_retirements where school_id=school and campus_id=campus.id))order by campus.id),'[]'::jsonb)into rows from(select*from app.campuses where school_id=school and(page_cursor is null or id>page_cursor)order by id limit page_limit+1)campus;return jsonb_build_object('items',case when jsonb_array_length(rows)>page_limit then rows-page_limit else rows end,'nextCursor',case when jsonb_array_length(rows)>page_limit then rows->(page_limit-1)->>'id'else null end);
end$$;
create function internal.read_class_campus(target_class uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();assignment app.class_campus_revisions;begin
 if not"authorization".school_operations_access(school)or not"authorization".can_view_class(school,target_class)or not exists(select 1 from app.classes where school_id=school and id=target_class and status='active')then raise exception 'Class campus scope denied'using errcode='42501';end if;select*into assignment from app.class_campus_revisions where school_id=school and class_id=target_class order by revision desc limit 1;return jsonb_build_object('id',target_class,'revision',coalesce(assignment.revision,0),'campusId',assignment.campus_id,'campusName',(select name from app.campuses where school_id=school and id=assignment.campus_id));
end$$;
create function internal.read_learning_support(filters jsonb)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();role_name text:="authorization".current_role("authorization".school_id());rows jsonb;lim integer:=(filters->>'limit')::integer;begin
 if filters is null or jsonb_typeof(filters)<>'object'or filters-'limit'-'cursor'-'courseId'-'assessmentId'-'learnerId'<>'{}'::jsonb or jsonb_typeof(filters->'limit')is distinct from'number'then raise exception 'Explicit bounded support scope required'using errcode='22023';end if;
 if role_name in('student','parent')and filters->>'courseId'is null and filters->>'assessmentId'is null then raise exception 'Exact supported learning context required'using errcode='42501';end if;
 if filters->>'assessmentId'is not null and not exists(select 1 from app.assessments assessment where assessment.school_id=school and assessment.id=(filters->>'assessmentId')::uuid and(filters->>'courseId'is null or assessment.course_id=(filters->>'courseId')::uuid)and"authorization".can_read_course(school,assessment.course_id))then raise exception 'Exact support assessment scope denied'using errcode='42501';end if;
 if not"authorization".school_operations_access(school)or not"authorization".academic_access(school)or role_name is null or role_name not in('admin','coordinator','teacher','student','parent')or lim is null or lim not between 1 and 25 then raise exception 'Learning support read denied'using errcode='42501';end if;
 with candidates as materialized(select support.*from app.learning_support_approvals support where support.school_id=school and(filters->>'cursor'is null or support.id>(filters->>'cursor')::uuid)and(filters->>'courseId'is null or support.course_id=(filters->>'courseId')::uuid)and(filters->>'assessmentId'is null or support.assessment_id is null or support.assessment_id=(filters->>'assessmentId')::uuid)and(filters->>'learnerId'is null or support.learner_id=(filters->>'learnerId')::uuid)
 and"authorization".current_learner_course(school,support.course_id,support.learner_id)and"authorization".can_view_person(school,support.learner_id)and"authorization".can_read_course(school,support.course_id)
 and(filters->>'assessmentId'is null or exists(select 1 from app.assessments selected where selected.school_id=school and selected.id=(filters->>'assessmentId')::uuid and selected.course_id=support.course_id))
 and(role_name in('admin','coordinator')or role_name='teacher'and"authorization".can_manage_course(school,support.course_id)or role_name='student'and support.learner_id="authorization".actor_id()and support.student_visible or role_name='parent'and support.parent_visible)
 and(role_name in('admin','coordinator','teacher')or internal.learning_published_content(school,'course',support.course_id)is not null)
 and(role_name in('admin','coordinator','teacher')or support.effective_from<=(clock_timestamp()at time zone'UTC')::date and support.effective_to>=(clock_timestamp()at time zone'UTC')::date and not exists(select 1 from app.learning_support_revocations revoked where revoked.school_id=school and revoked.support_id=support.id))order by support.id limit lim+1)
 select coalesce(jsonb_agg(jsonb_build_object('id',support.id,'learnerId',support.learner_id,'learnerName',person.display_name,'courseId',support.course_id,'courseTitle',coalesce(internal.learning_published_content(school,'course',course.id)->>'title',course.title),'assessmentId',support.assessment_id,'assessmentTitle',assessment.title,'title',support.title,'instructions',support.instructions,'effectiveFrom',support.effective_from,'effectiveTo',support.effective_to,'studentVisible',support.student_visible,'parentVisible',support.parent_visible,'revision',case when revoked.support_id is null then 1 else 2 end,'state',case when revoked.support_id is not null then'REVOKED'when support.effective_from>(clock_timestamp()at time zone'UTC')::date then'UPCOMING'when support.effective_to<(clock_timestamp()at time zone'UTC')::date then'EXPIRED'else'ACTIVE'end)||case when role_name in('admin','coordinator')then jsonb_build_object('approvalReason',support.reason)else'{}'::jsonb end order by support.id),'[]'::jsonb)into rows from candidates support join app.people person on person.school_id=support.school_id and person.actor_id=support.learner_id join app.courses course on course.school_id=support.school_id and course.id=support.course_id left join app.assessments assessment on assessment.school_id=support.school_id and assessment.id=support.assessment_id left join app.learning_support_revocations revoked on revoked.school_id=support.school_id and revoked.support_id=support.id;
 if octet_length(rows::text)>500000 then raise exception 'Choose a smaller support page'using errcode='22023';end if;return jsonb_build_object('items',case when jsonb_array_length(rows)>lim then rows-lim else rows end,'nextCursor',case when jsonb_array_length(rows)>lim then rows->(lim-1)->>'id'else null end);
end$$;
revoke execute on function internal.campus_support_command(text,uuid,jsonb,text,text,text),internal.read_campus_page(integer,uuid),internal.read_class_campus(uuid),internal.read_learning_support(jsonb)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.campus_support_command(text,uuid,jsonb,text,text,text),internal.read_campus_page(integer,uuid),internal.read_class_campus(uuid),internal.read_learning_support(jsonb)to cuevo_api;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'School context event dispatcher changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''school.context.approved'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.entity_type<>''school_context''or not(case e.metadata->>''command''when''campus.create''then exists(select 1 from app.campuses source where source.school_id=e.school_id and source.id=e.entity_id and source.created_by=e.actor_id and e.version=1)when''class.campus''then exists(select 1 from app.class_campus_revisions source where source.school_id=e.school_id and source.id=e.entity_id and source.approved_by=e.actor_id and source.revision=e.version)when''campus.retire''then exists(select 1 from app.campus_retirements source where source.school_id=e.school_id and source.campus_id=e.entity_id and source.retired_by=e.actor_id and e.version=1)when''support.create''then exists(select 1 from app.learning_support_approvals source where source.school_id=e.school_id and source.id=e.entity_id and source.approved_by=e.actor_id and e.version=1)when''support.revoke''then exists(select 1 from app.learning_support_revocations source where source.school_id=e.school_id and source.support_id=e.entity_id and source.revoked_by=e.actor_id and e.version=2)else false end)then raise exception ''School approved context event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''School context acknowledgement lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;
end$$;
commit;
